# =========================================================
# STORAGE
# =========================================================

DEFAULT_DATA = {
    "users": {},
    "access_requests": {},
    "states": {},
    "training_attempts": {},
    "profile_bindings": {},
    "next_request_id": 1,
    "next_attempt_id": 1
}

def utc_now_iso():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

def load_data():
    if not DATA_FILE.exists():
        data = json.loads(json.dumps(DEFAULT_DATA))
        save_data(data)
        return data
    try:
        data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
        for k, v in DEFAULT_DATA.items():
            if k not in data:
                data[k] = json.loads(json.dumps(v))
        return data
    except Exception:
        log.exception("Помилка читання локального сховища")
        return json.loads(json.dumps(DEFAULT_DATA))

def save_data(data):
    DATA_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8"
    )

def get_user(tg_id):
    return load_data()["users"].get(str(tg_id))

def upsert_user(tg_id, **kwargs):
    data = load_data()
    key = str(tg_id)
    user = data["users"].get(key, {
        "telegram_id": tg_id,
        "username": None,
        "full_name": None,
        "site": None,
        "position": None,
        "role": None,
        "status": "pending"
    })
    for k, v in kwargs.items():
        if v is not None:
            user[k] = v
    data["users"][key] = user
    save_data(data)

def set_state(tg_id, state, payload=None):
    data = load_data()
    data["states"][str(tg_id)] = {
        "state": state,
        "payload": payload or {}
    }
    save_data(data)

def get_state(tg_id):
    item = load_data()["states"].get(str(tg_id))
    if not item:
        return None, {}
    return item.get("state"), item.get("payload", {})

def clear_state(tg_id):
    data = load_data()
    data["states"].pop(str(tg_id), None)
    save_data(data)

def create_access_request(tg_id, username, site, role):
    data = load_data()
    req_id = int(data.get("next_request_id", 1))
    data["next_request_id"] = req_id + 1
    data["access_requests"][str(req_id)] = {
        "id": req_id,
        "telegram_id": tg_id,
        "username": username,
        "site": site,
        "role": role,
        "status": "new",
        "created_at": utc_now_iso()
    }
    save_data(data)
    return req_id

def get_access_request(req_id):
    return load_data()["access_requests"].get(str(req_id))

def update_access_request(req_id, status):
    data = load_data()
    row = data["access_requests"].get(str(req_id))
    if row:
        row["status"] = status
        data["access_requests"][str(req_id)] = row
        save_data(data)

def bind_profile(tg_id, identity):
    data = load_data()
    data["profile_bindings"][str(tg_id)] = {
        **identity,
        "bound_at": utc_now_iso()
    }
    user = data["users"].setdefault(str(tg_id), {"telegram_id": tg_id})
    user["site"] = identity["site"]
    user["position"] = identity["position"]
    user["full_name"] = identity["full_name"]
    data["users"][str(tg_id)] = user
    save_data(data)

def save_training_attempt(tg_id, attempt):
    data = load_data()
    attempt_id = int(data.get("next_attempt_id", 1))
    data["next_attempt_id"] = attempt_id + 1
    attempt["id"] = attempt_id
    attempt["telegram_id"] = tg_id
    attempt["finished_at"] = utc_now_iso()
    rows = data["training_attempts"].setdefault(str(tg_id), [])
    rows.append(attempt)
    data["training_attempts"][str(tg_id)] = rows[-30:]
    save_data(data)

def get_training_attempts(tg_id):
    return load_data()["training_attempts"].get(str(tg_id), [])

# =========================================================
# TELEGRAM
# =========================================================

def tg(method, payload=None):
    try:
        r = requests.post(
            f"{API}/{method}",
            json=payload or {},
            timeout=20
        )
        if not r.ok:
            log.error("Telegram %s: %s", method, r.text)
        return r.json()
    except Exception:
        log.exception("Telegram request failed: %s", method)
        return {"ok": False}

def send_message(chat_id, text, reply_markup=None):
    payload = {
        "chat_id": chat_id,
        "text": text,
        "parse_mode": "HTML"
    }
    if reply_markup:
        payload["reply_markup"] = reply_markup
    return tg("sendMessage", payload)

def edit_message(chat_id, message_id, text, reply_markup=None):
    payload = {
        "chat_id": chat_id,
        "message_id": message_id,
        "text": text,
        "parse_mode": "HTML"
    }
    if reply_markup is not None:
        payload["reply_markup"] = reply_markup
    return tg("editMessageText", payload)

def answer_callback(callback_id, text=None):
    payload = {"callback_query_id": callback_id}
    if text:
        payload["text"] = text[:180]
    return tg("answerCallbackQuery", payload)

def inline(rows):
    return {"inline_keyboard": rows}

