ALIASES = {
    "ваги":"автоваг",
    "автовагова":"автоваг",
    "ворота":"ворота",
    "кода":"кода",
    "свс":"свс",
    "скуд":"скуд",
    "генератор":"генератор",
    "топкова":"топкова",
    "втл":"втл",
    "сервер":"сервер",
}

def normalize_search(text):
    text = (text or "").lower()
    text = text.replace("’", "'").replace("`", "'")
    text = re.sub(
        r"[^а-яіїєґa-z0-9№' -]+",
        " ",
        text
    )
    return re.sub(r"\s+", " ", text).strip()

def search_objects(query):
    q = normalize_search(query)
    if not q:
        return []

    variants = [q]
    for alias, target in ALIASES.items():
        if alias in q:
            variants.append(q.replace(alias, target))

    found = []

    for obj in OBJECTS_BILOVODY:
        hay = normalize_search(obj["name"])
        score = 0

        for variant in variants:
            if variant == hay:
                score = max(score, 100)
            elif variant in hay:
                score = max(score, 80)
            else:
                words = [
                    w for w in variant.split()
                    if len(w) >= 2
                ]
                if words and all(w in hay for w in words):
                    score = max(score, 60)

        if score:
            found.append((score, obj))

    found.sort(
        key=lambda x: (-x[0], x[1]["name"])
    )
    return [x[1] for x in found[:8]]

def object_card(obj):
    seals = obj.get("seals")
    seals_text = (
        str(seals)
        if seals not in (None, "")
        else "не вказано / за категорією"
    )

    responsibles = obj.get("responsibles") or []
    resp_text = (
        "\n".join(
            f"• {escape(x)}"
            for x in responsibles[:6]
        )
        or "• не вказано"
    )

    return (
        f"🏢 <b>{escape(obj['name'])}</b>\n"
        f"🔖 Пломб: <b>{escape(seals_text)}</b>\n"
        f"🛡 Тип: <b>{escape(str(obj.get('guard_type') or '—'))}</b>\n"
        f"👤 МВО / відповідальні:\n"
        f"{resp_text}"
    )

