def procedure_keyboard():
    order = [
        "1","2","3",
        "4.1","4.2","4.3",
        "4.4","4.5","4.6",
        "4.7","4.8","4.9",
        "4.10","5"
    ]

    rows = []
    row = []

    for key in order:
        row.append({
            "text": key,
            "callback_data": f"proc:{key}"
        })

        if len(row) == 3:
            rows.append(row)
            row = []

    if row:
        rows.append(row)

    return inline(rows)

def leadership_keyboard():
    return inline([
        [{
            "text":"🏭 Керівництво ДЗ",
            "callback_data":"lead:DZ"
        }],
        [{
            "text":"🛡 Керівництво СБ",
            "callback_data":"lead:SB"
        }],
    ])

def show_leadership(chat_id, group):
    key = "ДЗ" if group == "DZ" else "СБ"
    rows = LEADERSHIP.get(key, [])

    if not rows:
        send_message(
            chat_id,
            f"👔 <b>Керівництво {escape(key)}</b>\n\n"
            "Дані ще не додані."
        )
        return

    for row in rows:
        phone = row.get("phone") or "не додано"

        send_message(
            chat_id,
            f"👔 <b>{escape(row['position'])}</b>\n"
            f"👤 {escape(row['full_name'])}\n"
            f"📞 {escape(phone)}\n"
            "📷 Фото: буде додано пізніше"
        )

