def my_results_text(tg_id):
    attempts = get_training_attempts(tg_id)

    if not attempts:
        return "📭 Завершених тестів поки немає."

    lines = [
        "🧠 <b>Мої результати</b>",
        ""
    ]

    for a in reversed(attempts[-5:]):
        icon = "✅" if a.get("passed") else "⚠️"
        date = (a.get("finished_at") or "")[:10]

        lines.append(
            f"{icon} {date} — "
            f"<b>{a.get('percent',0)}%</b> "
            f"({a.get('correct',0)}/{a.get('total',0)})"
        )

    best = max(
        a.get("percent",0)
        for a in attempts
    )

    lines += [
        "",
        f"🏆 Найкращий результат: <b>{best}%</b>"
    ]

    return "\n".join(lines)

