def handle_callback(cq):
    tg_id = cq["from"]["id"]
    data = cq.get("data","")
    username = cq["from"].get("username")

    if data.startswith("quiz:"):
        handle_quiz_callback(cq)
        return

    # ---------- ACCESS ----------
    if data.startswith("access:site:"):
        idx = int(data.rsplit(":",1)[1])
        site = SITES[idx]

        set_state(
            tg_id,
            "access_role",
            {"site": site}
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🔐 <b>Заявка на доступ</b>\n\n"
            f"🏢 {escape(site)}\n\n"
            "2/2. Обери посаду:",
            role_keyboard("access")
        )
        return

    if data.startswith("access:role:"):
        role = data.split(":",2)[2]
        state, payload = get_state(tg_id)

        if state != "access_role":
            answer_callback(
                cq["id"],
                "Почни заявку заново."
            )
            return

        submit_access_request(
            tg_id,
            username,
            payload["site"],
            role
        )

        answer_callback(
            cq["id"],
            "Заявку відправлено"
        )

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "✅ Заявку сформовано.",
            {"inline_keyboard":[]}
        )
        return

    # ---------- ADMIN APPROVE ----------
    if data.startswith("approve:") or data.startswith("reject:"):
        if tg_id != ADMIN_ID:
            answer_callback(
                cq["id"],
                "Недостатньо прав"
            )
            return

        action, req_id = data.split(":",1)
        req = get_access_request(req_id)

        if not req:
            answer_callback(
                cq["id"],
                "Заявку не знайдено"
            )
            return

        target = req["telegram_id"]

        if action == "approve":
            update_access_request(
                req_id,
                "approved"
            )

            upsert_user(
                target,
                site=req.get("site"),
                role=req.get("role"),
                position=ROLE_TO_POSITION.get(req.get("role")),
                status="active"
            )

            send_message(
                target,
                "✅ <b>Доступ надано.</b>\n\n"
                f"🏢 {escape(req.get('site') or '—')}\n"
                f"💼 {escape(ROLE_TO_POSITION.get(req.get('role'),'—'))}",
                main_menu(req.get("role"))
            )

            answer_callback(
                cq["id"],
                "Доступ надано"
            )

        else:
            update_access_request(
                req_id,
                "rejected"
            )

            upsert_user(
                target,
                status="rejected"
            )

            send_message(
                target,
                "❌ Заявку на доступ відхилено.",
                unauthorized_menu()
            )

            answer_callback(
                cq["id"],
                "Відхилено"
            )

        return

    # ---------- TEST IDENTITY ----------
    if data.startswith("test:site:"):
        idx = int(data.rsplit(":",1)[1])
        site = SITES[idx]
        state, payload = get_state(tg_id)
        mode = payload.get("mode","primary")

        set_state(
            tg_id,
            "test_role",
            {
                "mode": mode,
                "site": site
            }
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            f"🏢 {escape(site)}\n\n"
            "2/3. Обери посаду:",
            role_keyboard("test")
        )
        return

    if data.startswith("test:role:"):
        role = data.split(":",2)[2]
        position = ROLE_TO_POSITION.get(role)
        state, payload = get_state(tg_id)

        if state != "test_role":
            answer_callback(
                cq["id"],
                "Почни тест заново."
            )
            return

        site = payload["site"]
        mode = payload.get("mode","primary")
        staff = staff_for(site, position)

        if not staff:
            answer_callback(
                cq["id"],
                "Для цієї дільниці ПІБ ще не завантажені"
            )

            edit_message(
                tg_id,
                cq["message"]["message_id"],
                "📭 <b>Список ПІБ ще не завантажено</b>\n\n"
                f"🏢 {escape(site)}\n"
                f"💼 {escape(position)}\n\n"
                "Пізніше адміністратор додасть повний список.",
                inline([[
                    {
                        "text":"⬅️ Обрати іншу дільницю",
                        "callback_data":"test:restart"
                    }
                ]])
            )
            return

        set_state(
            tg_id,
            "test_staff",
            {
                "mode": mode,
                "site": site,
                "position": position
            }
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            f"🏢 {escape(site)}\n"
            f"💼 {escape(position)}\n\n"
            "3/3. Обери своє ПІБ:",
            staff_keyboard(
                site,
                position
            )
        )
        return

    if data == "test:restart":
        state, payload = get_state(tg_id)

        answer_callback(cq["id"])

        start_identity_flow(
            tg_id,
            payload.get("mode","primary")
        )
        return

    if data == "test:back:position":
        state, payload = get_state(tg_id)

        site = payload.get("site")
        mode = payload.get("mode","primary")

        set_state(
            tg_id,
            "test_role",
            {
                "mode": mode,
                "site": site
            }
        )

        answer_callback(cq["id"])

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "🎓 <b>Перед тестом</b>\n\n"
            "2/3. Обери посаду:",
            role_keyboard("test")
        )
        return

    if data.startswith("test:staff:"):
        staff_id = data.split(":",2)[2]
        state, payload = get_state(tg_id)

        if state != "test_staff":
            answer_callback(
                cq["id"],
                "Почни тест заново."
            )
            return

        person = next(
            (
                x for x in STAFF_DIRECTORY
                if x["id"] == staff_id
            ),
            None
        )

        if not person:
            answer_callback(
                cq["id"],
                "ПІБ не знайдено"
            )
            return

        expected_username = person.get("telegram_username")

        if expected_username:
            actual = (
                username or ""
            ).lstrip("@").lower()

            if actual != expected_username.lstrip("@").lower():
                answer_callback(
                    cq["id"],
                    "Це ПІБ прив’язане до іншого Telegram"
                )
                return

        identity = {
            "staff_id": person["id"],
            "site": payload["site"],
            "position": payload["position"],
            "full_name": person["full_name"]
        }

        answer_callback(
            cq["id"],
            "ПІБ підтверджено"
        )

        edit_message(
            tg_id,
            cq["message"]["message_id"],
            "✅ Дані підтверджено.",
            {"inline_keyboard":[]}
        )

        start_quiz(
            tg_id,
            identity,
            payload.get("mode","primary")
        )
        return

    # ---------- PROCEDURE ----------
    if data.startswith("proc:"):
        key = data.split(":",1)[1]
        sec = PROCEDURE_SECTIONS.get(key)

        answer_callback(cq["id"])

        if sec:
            edit_message(
                tg_id,
                cq["message"]["message_id"],
                f"📖 <b>{escape(key)}. {escape(sec['title'])}</b>\n\n"
                f"{escape(sec['text'])}",
                procedure_keyboard()
            )
        return

    # ---------- LEADERSHIP ----------
    if data.startswith("lead:"):
        group = data.split(":",1)[1]

        answer_callback(cq["id"])

        show_leadership(
            tg_id,
            group
        )
        return

    answer_callback(
        cq["id"],
        "Невідома дія"
    )

