def handle_start(msg):
    tg_id = msg["from"]["id"]
    username = msg["from"].get("username")

    if tg_id == ADMIN_ID:
        upsert_user(
            tg_id,
            username=username,
            full_name="Адміністратор",
            role="admin",
            status="active"
        )

        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Режим адміністратора.\n"
            "Версія: <b>v0.5</b>\n"
            "🧪 Тимчасове сховище без PostgreSQL.",
            admin_menu()
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Доступ закритий. Подай коротку заявку.",
            unauthorized_menu()
        )
        return

    send_message(
        tg_id,
        "🛡 <b>Службовий бот охорони</b>\n"
        f"🏢 {escape(user.get('site') or '—')}\n"
        f"💼 {escape(user.get('position') or ROLE_TO_POSITION.get(user.get('role'),'—'))}",
        main_menu(user.get("role"))
    )

def handle_text(msg):
    tg_id = msg["from"]["id"]
    text = (msg.get("text") or "").strip()

    if text == "/start":
        handle_start(msg)
        return

    # ---------- ADMIN ----------
    if tg_id == ADMIN_ID:
        if text == "🔐 Заявки":
            send_message(
                tg_id,
                admin_requests_text(),
                admin_menu()
            )
            return

        if text == "👥 Учасники":
            send_message(
                tg_id,
                admin_users_text(),
                admin_menu()
            )
            return

        if text == "🎓 Результати":
            send_message(
                tg_id,
                admin_results_text(),
                admin_menu()
            )
            return

        if text == "📊 Статистика":
            send_message(
                tg_id,
                admin_stats_text(),
                admin_menu()
            )
            return

        if text == "🏢 Дільниці":
            send_message(
                tg_id,
                admin_sites_text(),
                admin_menu()
            )
            return

        if text == "📚 База знань":
            send_message(
                tg_id,
                admin_knowledge_text(),
                admin_menu()
            )
            return

        if text == "👔 Керівництво":
            send_message(
                tg_id,
                "👔 <b>Керівництво ДЗ і СБ</b>\n\n"
                "Обери розділ:",
                leadership_keyboard()
            )
            return

        if text == "📖 Процедура":
            send_message(
                tg_id,
                "📖 <b>Процедура з організації охорони об’єктів</b>\n\n"
                "Обери розділ:",
                procedure_keyboard()
            )
            return

    state, payload = get_state(tg_id)

    if state == "quiz":
        send_message(
            tg_id,
            "🎓 Тест уже триває. "
            "Відповідай кнопками під питанням."
        )
        return

    if state == "object_search":
        results = search_objects(text)

        if not results:
            send_message(
                tg_id,
                "🔎 Нічого не знайдено.\n"
                "Спробуй коротше: <b>ворота</b>, "
                "<b>автоваг</b>, <b>СВС</b>, "
                "<b>генератор</b>, <b>ВТЛ</b>."
            )
        else:
            send_message(
                tg_id,
                f"🔎 Знайдено: <b>{len(results)}</b>"
            )

            for obj in results:
                send_message(
                    tg_id,
                    object_card(obj)
                )

        clear_state(tg_id)

        user = get_user(tg_id)

        send_message(
            tg_id,
            "🏠 Головне меню",
            main_menu((user or {}).get("role"))
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        if text in (
            "🔐 Подати заявку",
            "🔐 Подати заявку на доступ"
        ):
            start_access_request(tg_id)
        else:
            send_message(
                tg_id,
                "🔐 Доступ не надано.",
                unauthorized_menu()
            )
        return

    role = user.get("role")

    # ---------- TRAINING ----------
    if text == "🎓 Навчання":
        send_message(
            tg_id,
            "🎓 <b>Навчання та перевірка знань</b>\n\n"
            f"Тест: {TEST_QUESTION_COUNT} питань.\n"
            f"Цільовий результат: {PASS_PERCENT}%.",
            training_menu()
        )
        return

    if text == "📝 Почати тест":
        start_identity_flow(
            tg_id,
            "primary"
        )
        return

    if text == "🔄 Повторний тест":
        start_identity_flow(
            tg_id,
            "repeat"
        )
        return

    if text == "🧠 Мої результати":
        send_message(
            tg_id,
            my_results_text(tg_id),
            training_menu()
        )
        return

    if text == "📚 Матеріали":
        send_message(
            tg_id,
            "📚 <b>Тематичні блоки</b>\n\n"
            "💻 Цифрові технології\n"
            "🏢 Охорона об’єктів\n"
            "🛡 Реагування та затримання\n"
            "🚨 Повітряна тривога\n"
            "🩹 Домедична допомога\n"
            "🔥 Пожежна безпека",
            training_menu()
        )
        return

    if text == "⬅️ Головне меню":
        send_message(
            tg_id,
            "🏠 Головне меню",
            main_menu(role)
        )
        return

    # ---------- OBJECTS ----------
    if text == "🔎 Об'єкти":
        if (
            user.get("site")
            and user.get("site") != "Біловоди"
        ):
            send_message(
                tg_id,
                "🏢 Пошук об’єктів поки завантажений "
                "для дільниці <b>Біловоди</b>.\n"
                "Інші дільниці додамо після отримання "
                "їх Табелів постів.",
                main_menu(role)
            )
            return

        set_state(
            tg_id,
            "object_search",
            {}
        )

        send_message(
            tg_id,
            "🔎 <b>Пошук об’єкта — Біловоди</b>\n\n"
            "Введи назву або частину назви.\n"
            "Наприклад: <b>ворота</b>, <b>автоваг</b>, "
            "<b>КОДА</b>, <b>СВС</b>, <b>генератор</b>."
        )
        return

    # ---------- PROCEDURE ----------
    if text == "📖 Процедура":
        send_message(
            tg_id,
            "📖 <b>Процедура з організації охорони об’єктів</b>\n\n"
            "Обери розділ:",
            procedure_keyboard()
        )
        return

    # ---------- LEADERSHIP ----------
    if text == "👔 Керівництво":
        send_message(
            tg_id,
            "👔 <b>Керівництво ДЗ і СБ</b>\n\n"
            "Обери розділ:",
            leadership_keyboard()
        )
        return

    placeholders = {
        "🟢 Заступити":
            "🟡 Модуль зміни буде наступним етапом.",
        "🚶 Обхід":
            "🟡 Погодинні обходи буде підключено наступним етапом.",
        "⚠️ Недолік":
            "🟡 Реєстр недоліків буде окремим модулем.",
        "🚨 Подія":
            "🟡 Реєстр подій та тривог буде окремим модулем.",
        "👮 Склад зміни":
            "🟡 Склад зміни буде додано.",
        "✅ Контроль обходів":
            "🟡 Контроль обходів буде додано."
    }

    if text in placeholders:
        send_message(
            tg_id,
            placeholders[text],
            main_menu(role)
        )
        return

    send_message(
        tg_id,
        "Оберіть дію з меню.",
        main_menu(role)
    )

